import os
import sqlite3
import pandas as pd
import json

# Search for database files in the entire workspace
print("Searching for database files in the workspace...")
db_files = []

# Search common locations and parent directories
search_paths = ['/', '/home', '/workspace', '/content', '.']

for search_path in search_paths:
    if os.path.exists(search_path):
        for root, dirs, files in os.walk(search_path):
            for file in files:
                if file.endswith(('.db', '.sqlite', '.sqlite3')):
                    full_path = os.path.join(root, file)
                    db_files.append(full_path)
                    # Stop after finding a few to avoid excessive searching
                    if len(db_files) >= 10:
                        break
            if len(db_files) >= 10:
                break
    if len(db_files) >= 10:
        break

print(f"Found {len(db_files)} database files:")
for i, db_file in enumerate(db_files[:5]):  # Show first 5
    print(f"  {i+1}. {db_file}")

if db_files:
    # Try to connect to the first database found
    db_path = db_files[0]
    print(f"\nConnecting to database: {db_path}")

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        # Get all tables
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
        tables = cursor.fetchall()

        print(f"\nTables in database:")
        for table in tables:
            print(f"  - {table[0]}")

        # Look for tables that might contain audit policy data
        policy_tables = []
        for table in tables:
            table_name = table[0].lower()
            if any(keyword in table_name for keyword in ['audit', 'policy', 'sheet', 'data', 'directive']):
                policy_tables.append(table[0])

        if policy_tables:
            print(f"\nPotential policy tables: {policy_tables}")

            # Examine the first potential table
            table_name = policy_tables[0]
            print(f"\nExamining table: {table_name}")

            # Get table schema
            cursor.execute(f"PRAGMA table_info({table_name});")
            columns = cursor.fetchall()

            print(f"Columns in {table_name}:")
            for col in columns:
                print(f"  - {col[1]} ({col[2]})")

            # Get sample data
            cursor.execute(f"SELECT * FROM {table_name} LIMIT 5;")
            sample_rows = cursor.fetchall()

            print(f"\nSample data (first 5 rows):")
            for i, row in enumerate(sample_rows):
                print(f"Row {i+1}: {row}")

            # Get row count
            cursor.execute(f"SELECT COUNT(*) FROM {table_name};")
            total_rows = cursor.fetchone()[0]
            print(f"\nTotal rows in {table_name}: {total_rows}")

        else:
            print("\nNo tables with policy-related names found.")

        conn.close()

    except Exception as e:
        print(f"Error accessing database: {e}")
else:
    print("\nNo database files found. Let's check if there are any CSV or Excel files instead.")

    # Search for CSV or Excel files
    data_files = []
    for search_path in search_paths:
        if os.path.exists(search_path):
            for root, dirs, files in os.walk(search_path):
                for file in files:
                    if file.endswith(('.csv', '.xlsx', '.xls')):
                        full_path = os.path.join(root, file)
                        data_files.append(full_path)
                        if len(data_files) >= 10:
                            break
                if len(data_files) >= 10:
                    break
        if len(data_files) >= 10:
            break

    print(f"\nFound {len(data_files)} data files:")
    for i, data_file in enumerate(data_files[:5]):
        print(f"  {i+1}. {data_file}")
